import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.DkefD2kJ.js";const p=JSON.parse('{"title":"App settings","description":"","frontmatter":{},"headers":[],"relativePath":"app.md","filePath":"app.md"}'),s={name:"app.md"};function r(i,e,d,l,h,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="app-settings" tabindex="-1">App settings <a class="header-anchor" href="#app-settings" aria-label="Permalink to &quot;App settings&quot;">​</a></h1><h2 id="window-and-tray" tabindex="-1">Window and tray <a class="header-anchor" href="#window-and-tray" aria-label="Permalink to &quot;Window and tray&quot;">​</a></h2><p><strong>Settings, Interface</strong>:</p><ul><li><strong>Closing the window keeps Gameyfin running</strong>: the close button hides the window to the tray. Downloads run inside the app, so without this, closing the window stops them. After ten minutes in the tray the window is unloaded to free its memory, a few hundred MB. Downloads and save sync carry on; opening the window again takes a moment longer.</li><li><strong>Start Gameyfin when I log in</strong>: starts with your session, so background downloads keep going. <ul><li><strong>Start hidden in the tray</strong> (on by default): that start stays in the tray. Opening Gameyfin yourself, or the restart after an update, always shows the window.</li></ul></li><li><strong>Bring Gameyfin back when a game closes</strong> (on by default): raises the window once a game quits, where its save upload and any error are shown.</li><li><strong>Appearance</strong>: dark, light or match your system. <ul><li><strong>Draw with the graphics card</strong> (Linux, on by default): smoother scrolling. If Gameyfin ever closes before its window draws, it turns this off by itself for the next start. Changing it takes a restart.</li></ul></li></ul><p>While a game runs and the Gameyfin window has been in the background for a minute, the window is unloaded so the game gets its memory. Playtime, save sync and notifications carry on. It comes back when the game closes (with <strong>Bring Gameyfin back when a game closes</strong> on), or from the tray. Without a tray icon the window stays loaded.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p><strong>Settings, Interface</strong> has a main switch, <strong>Show notifications</strong>, and under it a switch per kind, all on by default. Turning the main switch off stops every popup and keeps your choices below it for when you turn it back on.</p><table tabindex="0"><thead><tr><th>Switch</th><th>Tells you</th></tr></thead><tbody><tr><td>Downloads and installs</td><td>A download is ready to install, or a game is ready to play.</td></tr><tr><td>Failures</td><td>A download, install or launch went wrong.</td></tr><tr><td>New versions of Gameyfin</td><td>A new release of the app.</td></tr><tr><td>New Proton versions</td><td>A newer build of a Proton you have downloaded.</td></tr><tr><td>Signed out</td><td>The server stopped accepting your sign-in.</td></tr><tr><td>Server connection</td><td>The server stopped answering for a few minutes, and when it is back.</td></tr><tr><td>Save sync</td><td>A save could not sync, or a save needs your choice.</td></tr><tr><td>New games</td><td>Games were added to the server, also while Gameyfin was closed.</td></tr><tr><td>Updated games</td><td>An installed game has new files on the server.</td></tr></tbody></table><p>Failures and sign-outs are always shown; the others stay quiet while you are looking at the window.</p><p>While you are signed in, Gameyfin checks the server every two minutes and the library every ten. A game counts as updated when its size on the server changes from the size you downloaded, which any Gameyfin server reports. Renaming a game&#39;s file or folder on the server makes it a new game instead.</p><p>Proton builds do not update by themselves, since a new build can break a game that ran. Gameyfin checks twice a day for a newer UMU-Proton, GE-Proton or Proton-CachyOS, only for the ones you have downloaded, and tells you once per release. Clicking it opens <strong>Settings, Compatibility</strong>, where <strong>Update to</strong> fetches it.</p><p>Clicking a notification opens Gameyfin on the page it is about. Every notification is also listed behind the bell in the title bar, even when its popup was switched off or held back. Click one to go to its page, dismiss it, or <strong>Dismiss all</strong>. The list clears when Gameyfin closes.</p><h2 id="offline" tabindex="-1">Offline <a class="header-anchor" href="#offline" aria-label="Permalink to &quot;Offline&quot;">​</a></h2><p>If the server cannot be reached, a banner says so and the library shows what is on this PC. Installed games stay playable. Everything refreshes when the server is back.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><p>Gameyfin checks GitHub once at startup (switch off in <strong>Settings, About</strong>). What happens next depends on how you installed it:</p><table tabindex="0"><thead><tr><th>Install</th><th>Updates</th></tr></thead><tbody><tr><td>Windows <code>.exe</code></td><td>Gameyfin downloads and applies the update itself.</td></tr><tr><td>Flatpak</td><td>Updates come from the Flatpak repository; the button runs the same update.</td></tr><tr><td><code>.deb</code>, <code>.rpm</code></td><td>Your package manager owns the files, so Gameyfin only tells you a new version exists.</td></tr></tbody></table><h2 id="account" tabindex="-1">Account <a class="header-anchor" href="#account" aria-label="Permalink to &quot;Account&quot;">​</a></h2><p><strong>Settings, Account</strong> shows the server, who you are signed in as and the connection status. On Gameyfin 2.6 or newer the app keeps you signed in with an API key, listed on the server under your personal access tokens by this device&#39;s name. Signing out removes it while the server still knows your browser session; otherwise delete it there. It also holds <strong>This device&#39;s name</strong>, shown beside every save this PC uploads, and <strong>Sign out</strong>.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Settings, Diagnostics</strong>:</p><ul><li><strong>Log files</strong>: one per day. Attach the newest when reporting a problem.</li><li><strong>Log detail</strong>: set it to Debug while reproducing a problem.</li><li><strong>App data</strong>: settings, session and local records.</li><li><strong>Artwork cache</strong>: cleans itself, or press <strong>Clear</strong> if covers look wrong.</li><li><strong>Reset settings</strong>: puts every setting back to its default. Your server, sign-in, games folders, save location and per-game options stay.</li></ul><p>Passwords for archives and WebDAV are stored in the settings file, readable only by your user account, but not encrypted.</p>',23)])])}const u=t(s,[["render",r]]);export{p as __pageData,u as default};
